refentry.refsect1:
&reftitle.description;

 public intYaf_Config_Ini::count


Retourne le nombre d'entrées de configuration de premier niveau.

  &reftitle.examples;

   Exemple avec Yaf_Config_Ini::count


<?php
/**
 * En supposant que /etc/myapp/application.ini contient :
 * [common]
 * application.name = "MyApp"
 * database.host    = "localhost"
 * database.port    = 3306
 */
$config = new Yaf_Config_Ini('/etc/myapp/application.ini', 'common');

// Seules les entrées de premier niveau ("application" et "database") sont comptées
var_dump(count($config));
var_dump($config->count());
?>


   &example.outputs.similar;


int(2)
int(2)
